import React from 'react';

import PageLoader from '@components/PageLoader';
import PohBreadcrumbs from '@ui-kit/Breadcrumb';
import PohButton, { ButtonSize, ButtonVariant } from '@ui-kit/Button';
import Empty from '@ui-kit/Empty';
import PohContainer from '@ui-kit/layout/Container';

import { getHikingDataAsync } from '../@services/hiking.service';
import { getHikingRepairKitItems } from '../@services/hikingRepairKit.service';
import { IHikingData } from '../@types/hiking.types';
import { IHikingRepairKit } from '../@types/hikingRepairKit.types';

const HikingRepairKitPrintPage: React.FC<{ id_hiking: number }> = ({ id_hiking }) => {
  const [hikingData, setHikingData] = React.useState<IHikingData | null>(null);
  const [repairKitItems, setHikingRepairKitItems] = React.useState<IHikingRepairKit[] | null>(null);

  React.useEffect(() => {
    getHikingDataAsync(id_hiking).then(setHikingData);
    getHikingRepairKitItems(id_hiking).then(setHikingRepairKitItems);
  }, [id_hiking]);

  if (hikingData == null || repairKitItems == null) {
    return <PageLoader />;
  }

  const daysCount = Math.round(
    (hikingData.finish.getTime() - hikingData.start.getTime()) / 86400000,
  );

  return (
    <div>
      <div className="d-print-none">
        <PohBreadcrumbs
          data={[
            { href: '/hiking', text: 'Походы' },
            { href: `/hiking/${id_hiking}`, text: hikingData.name },
            { href: `/hiking/${id_hiking}/repair-kit`, text: 'Ремнабор' },
            {
              href: `/hiking/${id_hiking}/repair-kit/print`,
              text: 'Печать вкладыша',
              active: true,
            },
          ]}
        />
      </div>

      <PohContainer>
        <header className="d-flex align-items-center justify-content-between">
          <h3>Ремнабор похода &laquo;{hikingData.name}&raquo;</h3>
          <aside className="d-print-none">
            <PohButton
              size={ButtonSize.Small}
              variant={ButtonVariant.Success}
              onClick={() => window.print()}
              disabled={repairKitItems.length === 0}
            >
              Печать
            </PohButton>
          </aside>
        </header>
        {repairKitItems.length === 0 ? (
          <Empty>Ремнабор не настроен</Empty>
        ) : (
          <table className="table table-sm table-condensed table-bordered">
            <thead>
              <tr>
                <th rowSpan={2}>Название</th>
                <th rowSpan={2}>Вес</th>
                <th rowSpan={2}>Комментарий</th>
                <th colSpan={3}>Использование</th>
              </tr>
              <tr>
                <th style={{ width: 120 }}>Дата</th>
                <th style={{ width: 120 }}>Участник</th>
                <th>Комментарий</th>
              </tr>
            </thead>
            <tbody>
              {repairKitItems.map((m) => (
                <tr key={m.id}>
                  <td>{m.name}</td>
                  <td className="text-end">{m.weight}</td>
                  <td style={{ whiteSpace: 'pre-wrap' }}>
                    <small>
                      {m.comment}{' '}
                      {m.assignee && ['отв.', m.assignee.name, m.assignee.surname].join(' ')}
                    </small>
                  </td>
                  <td>
                    {Array(daysCount)
                      .fill('')
                      .map((_, i) => (
                        <div key={i} className="border-bottom">
                          &nbsp;
                        </div>
                      ))}
                  </td>
                  <td>
                    {Array(daysCount)
                      .fill('')
                      .map((_, i) => (
                        <div key={i} className="border-bottom">
                          &nbsp;
                        </div>
                      ))}
                  </td>
                  <td>
                    {Array(daysCount)
                      .fill('')
                      .map((_, i) => (
                        <div key={i} className="border-bottom">
                          &nbsp;
                        </div>
                      ))}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </PohContainer>
    </div>
  );
};

export default HikingRepairKitPrintPage;
